<template><section class="sandbox-form"><div class="field-grid"><label>商品标题<input v-model="form.productTitle" placeholder="例如：校园随行杯" /></label><label>商品分类<input v-model="form.category" placeholder="例如：日用百货" /></label><label>模拟售价<input v-model.number="form.price" type="number" min="0" step="0.01" placeholder="29.90" /></label><label>库存<input v-model.number="form.stock" type="number" min="0" step="1" /></label><label>预警库存<input v-model.number="form.warningStock" type="number" min="0" step="1" /></label><label>评价回复<input v-model="form.reviewReply" placeholder="感谢支持" /></label></div><div class="preview"><span class="preview-icon">▣</span><div><strong>{{ form.productTitle || '待填写商品' }}</strong><small>库存 {{ form.stock || 0 }} · 预警线 {{ form.warningStock || 0 }}</small></div><span class="price">¥{{ Number(form.price || 0).toFixed(2) }}</span></div></section></template>
<script setup lang="ts">const props = defineProps<{ modelValue: Record<string, unknown> }>(); const emit = defineEmits<{ 'update:modelValue': [Record<string, unknown>] }>(); const form = computed({ get: () => props.modelValue, set: value => emit('update:modelValue', value) }); watch(form, value => emit('update:modelValue', { ...value }), { deep: true })</script>
<style scoped>.sandbox-form{padding:4px}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}label{display:grid;gap:7px;color:#344054;font-size:13px;font-weight:700}input{width:100%;box-sizing:border-box;min-height:40px;padding:0 11px;border:1px solid #d0d5dd;border-radius:6px;background:#fff;color:#172033;font:inherit;font-weight:400}.preview{display:flex;align-items:center;gap:12px;margin-top:22px;padding:13px;background:#f8fafc;border:1px solid #eaecf0;border-radius:6px}.preview-icon{display:grid;place-items:center;width:38px;height:38px;background:#e0f2fe;color:#0369a1;border-radius:5px}.preview div{display:grid;gap:3px;min-width:0}.preview strong{font-size:13px}.preview small{color:#7b8494;font-size:12px}.price{margin-left:auto;color:#d92d20;font-weight:800}@media(max-width:560px){.field-grid{grid-template-columns:1fr}}</style>
